import json

data=json.load(open('benchmark/source_data.json'))
sp={r['country']:r for r in data['education_spending']['data']}
pisa={r['country']:r for r in data['pisa_scores']['data']}
enr={r['country']:r for r in data['tertiary_enrollment']['data']}
yu={r['country']:r for r in data['youth_unemployment']['data']}

rows=[]
for c in sorted(sp.keys()):
  rows.append({
    'country':c,
    'region':sp[c]['region'],
    'spend':sp[c]['edu_spending_pct_gdp'],
    'pisa':pisa[c]['pisa_avg'],
    'enroll':enr[c]['enrollment_rate'],
    'yu':yu[c]['youth_unemp_rate'],
  })

regions=sorted({r['region'] for r in rows})
print('regions',regions)
# compute min/max
mins={k:min(r[k] for r in rows) for k in ['spend','pisa','enroll','yu']}
maxs={k:max(r[k] for r in rows) for k in ['spend','pisa','enroll','yu']}
print('mins',mins)
print('maxs',maxs)

# scale enroll to bubble size 6..18
emin,emax=mins['enroll'],maxs['enroll']

def scale(val, vmin, vmax, outmin, outmax):
  return outmin + (val - vmin) * (outmax - outmin) / (vmax - vmin)

def fmt_label(c):
  return c.replace('United States','USA').replace('United Kingdom','UK')

for r in rows:
  r['bubble']=round(scale(r['enroll'],emin,emax,6,18),1)

labels={'Costa Rica','Sweden','Norway','Denmark','Singapore','Japan','South Korea','Estonia','Spain','Greece','Italy'}

for r in rows:
  r['label']=fmt_label(r['country']) if r['country'] in labels else ''

# dump for chart
print('sample',rows[0])

# Output mermaid scatter data lines per region
reg_map={}
for reg in regions:
  reg_map[reg]=[r for r in rows if r['region']==reg]

for reg in regions:
  print(reg, len(reg_map[reg]))
